#include <algorithm>
#include <fstream>
#include <iostream>
#include <memory>
#include <string>
#include <vector>
using namespace std;
class Person{protected:int id;string name,contact;public:Person(int i,string n,string c):id(i),name(move(n)),contact(move(c)){}virtual~Person()=default;int getId()const{return id;}const string&getName()const{return name;}virtual string role()const=0;};
class Client:public Person{vector<int>history;public:using Person::Person;string role()const override{return"Client";}void addDeal(int x){history.push_back(x);}};
class Agent:public Person{double commissionRate;vector<int>properties,deals;public:Agent(int i,string n,string c,double r):Person(i,move(n),move(c)),commissionRate(r){}string role()const override{return"Agent";}double rate()const{return commissionRate;}void assign(int p){if(find(properties.begin(),properties.end(),p)==properties.end())properties.push_back(p);}void sold(int d){deals.push_back(d);}size_t performance()const{return deals.size();}};
class Property{protected:int id;string address,city,owner,status="Available";double area,price;int rooms,agentId=0;public:Property(int i,string a,string c,double ar,int r,double p,string o):id(i),address(move(a)),city(move(c)),owner(move(o)),area(ar),price(p),rooms(r){}virtual~Property()=default;int getId()const{return id;}double getPrice()const{return price;}const string&getCity()const{return city;}const string&getStatus()const{return status;}int getAgent()const{return agentId;}void assign(int a){agentId=a;}void setStatus(string s){status=move(s);}virtual string type()const=0;virtual string feature()const=0;void show()const{cout<<id<<" | "<<type()<<" | "<<address<<", "<<city<<" | "<<area<<" sqm | rooms "<<rooms<<" | "<<price<<" | owner "<<owner<<" | agent "<<agentId<<" | "<<status<<" | "<<feature()<<'\n';}};
class Apartment:public Property{int floor;public:Apartment(int i,string a,string c,double ar,int r,double p,string o,int f):Property(i,move(a),move(c),ar,r,p,move(o)),floor(f){}string type()const override{return"Apartment";}string feature()const override{return"floor "+to_string(floor);}};class Villa:public Property{bool garden;public:Villa(int i,string a,string c,double ar,int r,double p,string o,bool g):Property(i,move(a),move(c),ar,r,p,move(o)),garden(g){}string type()const override{return"Villa";}string feature()const override{return garden?"garden":"no garden";}};class Office:public Property{public:using Property::Property;string type()const override{return"Office";}string feature()const override{return"commercial";}};class Land:public Property{public:using Property::Property;string type()const override{return"Land";}string feature()const override{return"land parcel";}};
struct Transaction{int id,propertyId,clientId,agentId;string type,date;double amount,commission;};
class Agency{vector<shared_ptr<Property>>properties;vector<shared_ptr<Client>>clients;vector<shared_ptr<Agent>>agents;vector<Transaction>transactions;int nextProp=1,nextTx=1;shared_ptr<Property>prop(int id){for(auto&p:properties)if(p->getId()==id)return p;return{};}shared_ptr<Client>client(int id){for(auto&c:clients)if(c->getId()==id)return c;return{};}shared_ptr<Agent>agent(int id){for(auto&a:agents)if(a->getId()==id)return a;return{};}public:void addProperty(){int type,rooms;double area,price;string address,city,owner;cout<<"Type 1 Apartment 2 Villa 3 Office 4 Land: ";cin>>type;cout<<"Address: ";cin>>ws;getline(cin,address);cout<<"City: ";getline(cin,city);cout<<"Area rooms price: ";cin>>area>>rooms>>price;cout<<"Owner: ";cin>>ws;getline(cin,owner);int id=nextProp++;if(type==1){int floor;cout<<"Floor: ";cin>>floor;properties.push_back(make_shared<Apartment>(id,address,city,area,rooms,price,owner,floor));}else if(type==2){int garden;cout<<"Garden 1/0: ";cin>>garden;properties.push_back(make_shared<Villa>(id,address,city,area,rooms,price,owner,garden));}else if(type==3)properties.push_back(make_shared<Office>(id,address,city,area,rooms,price,owner));else properties.push_back(make_shared<Land>(id,address,city,area,rooms,price,owner));cout<<"Property ID "<<id<<'\n';}void addClient(){int id;string n,c;cin>>id;cin>>ws;getline(cin,n);getline(cin,c);if(!client(id))clients.push_back(make_shared<Client>(id,n,c));}void addAgent(){int id;double rate;string n,c;cin>>id;cin>>ws;getline(cin,n);getline(cin,c);cin>>rate;if(!agent(id))agents.push_back(make_shared<Agent>(id,n,c,rate/100.0));}void assign(){int pid,aid;cin>>pid>>aid;auto p=prop(pid);auto a=agent(aid);if(p&&a){p->assign(aid);a->assign(pid);}}void search(){int mode;cin>>mode;if(mode==1){string city;cin>>city;for(auto&p:properties)if(p->getCity()==city)p->show();}else if(mode==2){double lo,hi;cin>>lo>>hi;for(auto&p:properties)if(p->getPrice()>=lo&&p->getPrice()<=hi)p->show();}else{string status;cin>>status;for(auto&p:properties)if(p->getStatus()==status)p->show();}}void deal(){int pid,cid;string type,date;cin>>pid>>cid>>type>>date;auto p=prop(pid);auto c=client(cid);if(!p||!c||p->getStatus()!="Available")return;auto a=agent(p->getAgent());double commission=p->getPrice()*(a?a->rate():.03);int id=nextTx++;transactions.push_back({id,pid,cid,p->getAgent(),type,date,p->getPrice(),commission});p->setStatus(type=="Sale"?"Sold":"Rented");c->addDeal(id);if(a)a->sold(id);cout<<"Transaction "<<id<<" commission "<<commission<<'\n';}void list()const{for(auto&p:properties)p->show();}void report()const{double commissions=0;for(auto&t:transactions)commissions+=t.commission;cout<<"Properties "<<properties.size()<<" | deals "<<transactions.size()<<" | commissions "<<commissions<<'\n';for(auto&a:agents)cout<<a->getName()<<" deals="<<a->performance()<<'\n';}void save()const{ofstream o("transactions.txt");for(auto&t:transactions)o<<t.id<<'|'<<t.propertyId<<'|'<<t.clientId<<'|'<<t.agentId<<'|'<<t.type<<'|'<<t.date<<'|'<<t.amount<<'|'<<t.commission<<'\n';}void run(){for(;;){cout<<"\nReal Estate\n1 Property 2 Client 3 Agent 4 Assign agent 5 Search 6 Sale/Rental 7 List 8 Reports 0 Exit\n";int c;if(!(cin>>c)||c==0){save();break;}if(c==1)addProperty();else if(c==2)addClient();else if(c==3)addAgent();else if(c==4)assign();else if(c==5)search();else if(c==6)deal();else if(c==7)list();else if(c==8)report();}}};int main(){Agency{}.run();}
